const input = String($json.body?.chatInput || '').trim();
const sessionId = String($json.body?.sessionId || 'router-session');
const normalize = (value) => value
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const text = normalize(input);
const hasAny = (words) => words.some((word) => text.includes(word));

let module = 'dashboard';
let webhook = 'repuestos-chat-v2';
let confidence = 'media';
let reason = 'Consulta general o ambigua.';

if (!text || text.length < 2) {
  module = 'dashboard';
  webhook = 'repuestos-chat-v2';
  confidence = 'baja';
  reason = 'Mensaje vacio o demasiado corto.';
} else if (hasAny(['venta', 'vendimos', 'vendido', 'facturacion', 'boleta', 'historial de venta', 'metodo de pago', 'cobro de venta'])) {
  module = 'sales';
  webhook = 'repuestos-ventas';
  confidence = 'alta';
  reason = 'Consulta relacionada con ventas.';
} else if (hasAny(['caja', 'finanza', 'ganancia', 'utilidad', 'egreso', 'ingreso', 'cuentas por cobrar', 'flujo de caja', 'abono'])) {
  module = 'finance';
  webhook = 'repuestos-finanzas';
  confidence = 'alta';
  reason = 'Consulta relacionada con caja o finanzas.';
} else if (hasAny(['cliente', 'crm', 'deudor', 'premium', 'frecuente', 'cartera', 'fidelidad'])) {
  module = 'clients';
  webhook = 'repuestos-clientes';
  confidence = 'alta';
  reason = 'Consulta relacionada con clientes.';
} else if (hasAny(['compra', 'proveedor', 'pedido', 'abastecimiento', 'recepcion', 'recibido'])) {
  module = 'purchases';
  webhook = 'repuestos-compras';
  confidence = 'alta';
  reason = 'Consulta relacionada con compras o proveedores.';
} else if (hasAny(['produccion', 'fabrica', 'torneria', 'orden de produccion', 'lote', 'fabricar'])) {
  module = 'production';
  webhook = 'repuestos-produccion';
  confidence = 'alta';
  reason = 'Consulta relacionada con produccion.';
} else if (hasAny(['empleado', 'personal', 'operario', 'vendedor', 'turno', 'cargo'])) {
  module = 'employees';
  webhook = 'repuestos-empleados';
  confidence = 'alta';
  reason = 'Consulta relacionada con empleados.';
} else if (hasAny(['usuario', 'rol', 'permiso', 'acceso', 'cuenta del sistema'])) {
  module = 'users';
  webhook = 'repuestos-usuarios';
  confidence = 'alta';
  reason = 'Consulta relacionada con usuarios o roles.';
} else if (hasAny(['repuesto', 'repuestos', 'stock', 'oem', 'precio', 'ubicacion', 'donde esta', 'compatible', 'compatibilidad', 'catalogo', 'inventario', 'producto', 'productos', 'bujia', 'filtro', 'aceite', 'hilux', 'corolla', 'bosch', 'brembo', 'denso', 'toyota'])) {
  module = 'inventory';
  webhook = 'repuestos-inventario';
  confidence = 'alta';
  reason = 'Consulta relacionada con inventario o repuestos.';
} else if (hasAny(['dashboard', 'panel', 'kpi', 'indicador', 'estado general', 'situacion actual', 'resumen del sistema', 'como esta el negocio'])) {
  module = 'dashboard';
  webhook = 'repuestos-chat-v2';
  confidence = 'alta';
  reason = 'Consulta relacionada con dashboard.';
}

return [{
  json: {
    chatInput: input,
    sessionId,
    module,
    webhook,
    confidence,
    reason,
    targetUrl: `http://host.docker.internal:5678/webhook/${webhook}`
  }
}];

const response = $input.first().json;
let output = '';

if (Array.isArray(response) && response[0]?.output) {
  output = response[0].output;
} else if (typeof response?.output === 'string') {
  output = response.output;
} else if (typeof response?.response === 'string') {
  output = response.response;
} else if (typeof response === 'string') {
  output = response;
} else {
  output = JSON.stringify(response);
}

return [{ json: { output: output || 'No pude obtener respuesta del agente especifico.' } }];
